import{api}from'./api.js';
import{sb}from'./supabase-client.js';
import{COUNTRY_FALLBACK,countryFromStorage,money}from'./app-config.js';
import{normalizeBusinessConfig,getGeneralConfig,getLandingConfig,getChatConfig,getTaskConfig,getReferralConfig,getWithdrawalConfig,getKycConfig,getFeatureFlags,getPublicOrigin}from'./config-runtime.js';
import{configureRouter,navigate,resolveRoute}from'./router.js';

const RELEASE='20260802-stability-r2';
const app={session:null,user:null,state:null,profile:null,config:null,country:countryFromStorage(),suggestedCountry:null,taskClaim:null,chat:null,chatTimer:null,presenceTimer:null,explicitLogout:false,authVerifyTimer:null,sessionVerifyPromise:null,lastSessionVerifiedAt:0,adminModule:null};
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const showMessage=(id,text,type='error')=>{const e=$(id);if(!e)return;e.textContent=text;e.className=`form-message ${type} show`};
const clearMessage=id=>{const e=$(id);if(e)e.className='form-message'};
const profile=()=>app.profile||{};
const country=()=>profile().country||app.country||'NG';
const cmeta=()=>COUNTRY_FALLBACK[country()]||COUNTRY_FALLBACK.NG;
const level=()=>profile().level_name||'Starter';
const levels=()=>app.config?.levels||{};
const levelConfig=()=>levels()[level()]||{chat_limit:4,chat_reward_ngn:250,withdraw_min_ngn:40000,withdraw_max_ngn:120000};
const amountFromBase=base=>Math.round(Number(base||0)*(country()==='KE'?Number(app.config?.settings?.kenya_multiplier||.6):1));
const format=amount=>money(amount,country());
const loggedIn=()=>!!app.session?.user;
const uuid=()=>globalThis.crypto?.randomUUID?.()||`ec-${Date.now()}-${Math.random().toString(36).slice(2)}`;
const initials=name=>(String(name||'Member').trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('')||'M').toUpperCase();
const inferCountry=()=>{const tz=Intl.DateTimeFormat().resolvedOptions().timeZone||'',langs=(navigator.languages||[navigator.language||'']).join(' ').toLowerCase();if(/nairobi/i.test(tz)||/sw-ke|en-ke/.test(langs))return'KE';if(/lagos/i.test(tz)||/en-ng/.test(langs))return'NG';return'NG'};
const greeting=()=>{const h=new Date().getHours();return h<12?'Good morning':h<18?'Good afternoon':'Good evening'};
const safeHttps=value=>{try{const u=new URL(String(value||'').trim());return u.protocol==='https:'?u:null}catch{return null}};
const serverTime=value=>{const n=Date.parse(value||'');return Number.isFinite(n)?n:Date.now()};
const normalizedConfig=()=>normalizeBusinessConfig(app.config||{});
const generalConfig=()=>getGeneralConfig(app.config||{});
const landingConfig=()=>getLandingConfig(app.config||{});
const chatConfig=()=>getChatConfig(app.config||{});
const taskConfig=()=>getTaskConfig(app.config||{});
const referralConfig=()=>getReferralConfig(app.config||{});
const withdrawalConfig=()=>getWithdrawalConfig(app.config||{});
const kycConfig=()=>getKycConfig(app.config||{});
const featureFlags=()=>getFeatureFlags(app.config||{});
const chatPartners=()=>chatConfig().partners;
const chatMinimumSeconds=()=>chatConfig().minimum_seconds;
const chatRequiredReplies=()=>chatConfig().required_replies;
const chatMinimumReplyLength=()=>chatConfig().minimum_reply_length;
const chatRecoveryMs=()=>chatConfig().recovery_expiry_minutes*60000;
const chatRecoveryKey=()=>`earnchat-chat-recovery:${app.user?.id||'guest'}`;
const chatPromptSets=()=>chatConfig().prompt_sets;
const chatPrompts=()=>{const sets=chatPromptSets();return sets[Number(app.chat?.promptSet||0)]||sets[0]};
const choosePromptSet=seed=>{const sets=chatPromptSets();let hash=0;for(const c of String(seed||Date.now()))hash=(hash*31+c.charCodeAt(0))>>>0;let index=hash%sets.length;const last=Number(localStorage.getItem('earnchat-last-prompt-set'));if(Number.isInteger(last)&&index===last&&sets.length>1)index=(index+1)%sets.length;localStorage.setItem('earnchat-last-prompt-set',String(index));return index};

function setCountry(code,{persist=true,render=true}={}){app.country=code==='KE'?'KE':'NG';if(persist)localStorage.setItem('earnchat-country',app.country);if(render){renderLanding();renderSignupCountry()}}
function renderSignupCountry(){const selected=app.country,general=generalConfig(),enabled=new Set(general.enabled_countries);$$('.country-card[data-country]').forEach(b=>{const available=enabled.has(b.dataset.country),active=b.dataset.country===selected&&available;b.classList.toggle('selected',active);b.classList.toggle('hidden',!available);b.disabled=!available;b.setAttribute('aria-pressed',String(active))});const c=COUNTRY_FALLBACK[selected],starter=levels().Starter||{},settings=app.config?.settings||{},multiplier=selected==='KE'?Number(settings.kenya_multiplier||.6):Number(settings.nigeria_multiplier||1),reward=money(Math.round(Number(starter.chat_reward_ngn||250)*multiplier),selected),signup=money(Math.round(Number(settings.signup_bonus_ngn||2000)*multiplier),selected),summary=$('#signup-country-summary');if(summary)summary.innerHTML=enabled.has(selected)?`<b>${selected==='KE'?'🇰🇪 Kenya':'🇳🇬 Nigeria'} selected</b><br>Currency: ${c.currency} · Welcome bonus: ${signup} · Starter chat: ${reward}<br>Main payout: ${selected==='KE'?'M-Pesa or bank transfer':'Bank transfer'}`:'<b>This country is not currently accepting registrations.</b>';const submit=$('#register-submit');if(submit){submit.disabled=!enabled.has(selected)||!general.registration_enabled;submit.textContent=general.registration_enabled?'Create secure account':'Registration unavailable'}}
function showCountrySuggestion(){if(localStorage.getItem('earnchat-country-confirmed'))return;const code=app.suggestedCountry||app.country,c=COUNTRY_FALLBACK[code],notice=$('#country-notice');if(!notice)return;$('#country-notice-title').textContent=`${code==='KE'?'🇰🇪 Kenya':'🇳🇬 Nigeria'} suggested`;$('#country-notice-copy').textContent=`Your browser suggests ${c.name}. Confirm before signup; you can choose the other country.`;$('#country-notice-confirm').textContent=`Continue with ${c.name}`;notice.classList.remove('hidden')}
function landingValues(){const settings=app.config?.settings||{},starter=app.config?.levels?.Starter?.chat_reward_ngn??250,multiplier=app.country==='KE'?Number(settings.kenya_multiplier||.6):Number(settings.nigeria_multiplier||1),chat=Math.round(starter*multiplier),cycle=Math.round(Number(settings.daily_cap_ngn||20000)*multiplier),signup=Math.round(Number(settings.signup_bonus_ngn||2000)*multiplier);return{chat,cycle,signup}}
function renderLanding(){const c=COUNTRY_FALLBACK[app.country],v=landingValues(),cycle=money(v.cycle,app.country),chat=money(v.chat,app.country),landing=landingConfig(),general=generalConfig();$('#landing-title').textContent=landing.headline;$('#landing-copy').innerHTML=`${esc(landing.subheadline)}<br><strong>Earn up to ${cycle} during your activity cycle.</strong>`;$('#landing-chat').textContent=chat;$('#landing-chat-detail').textContent=`${chat} per approved Starter chat`;$('#landing-cta').textContent=general.registration_enabled?landing.cta_label:'Registration unavailable';$('#landing-cta').disabled=!general.registration_enabled;$('#landing-note').textContent=general.maintenance_mode?general.maintenance_message:(app.country==='KE'?'No payment required · Beginner friendly · M-Pesa supported':'No payment required · Beginner friendly · Secure signup');$('#country-switch').textContent=`${app.country==='KE'?'🇰🇪':'🇳🇬'} ${c.name}`;$('#preview-balance').textContent=money(v.signup,app.country);$('#final-cta-copy').textContent=`Continue with ${c.name}. Your ${c.currency} earning currency will be confirmed during signup.`;const preview=$('.phone-preview');if(preview&&!$('.example-label',preview)){const label=document.createElement('small');label.className='example-label';label.textContent='EXAMPLE DASHBOARD';preview.prepend(label)}loadPublicLanding()}
async function loadPublicLanding(){const landing=landingConfig(),section=$('#social-proof-section');if(!landing.social_proof_enabled){section?.classList.add('hidden');return}let payments=[],feedback=[];if(landing.verified_payments_enabled){try{payments=(await api.payments()||[]).filter(r=>(r.country_code||'NG')===app.country)}catch{}}if(landing.member_feedback_enabled){try{feedback=(await api.feedback()||[]).filter(r=>(r.country_code||'NG')===app.country)}catch{}}if(!section)return;if(!payments.length&&!feedback.length){section.classList.add('hidden');return}section.classList.remove('hidden');const paymentList=$('#payment-list'),feedbackList=$('#member-feedback-list');if(paymentList)paymentList.innerHTML=payments.map(r=>`<article class="list-card"><header><div><h3>${esc(r.masked_name)} · ${r.country_code==='KE'?'🇰🇪 Kenya':'🇳🇬 Nigeria'}</h3><p>${esc(r.payout_method)} · Paid ${new Date(r.paid_at).toLocaleDateString()}</p></div><b class="reward">${r.currency==='KES'?'KSh ':'₦'}${Number(r.amount).toLocaleString()}</b></header></article>`).join('');if(feedbackList)feedbackList.innerHTML=feedback.map(r=>`<article class="list-card"><div class="phone-top"><div class="mini-avatar">${r.country_code==='KE'?'K':'N'}</div><div><b>Verified paid member</b><small>${r.country_code==='KE'?'🇰🇪 Kenya':'🇳🇬 Nigeria'}</small></div></div><p>“${esc(r.quote)}”</p></article>`).join('')}

function renderAppHeader(title,subtitle=''){const view=$('.view.active');if(!view)return;const h=$('.app-header h1',view);if(h)h.textContent=title;const s=$('.app-header small',view);if(s)s.textContent=subtitle;const p=$('.app-header .pill',view);if(p&&!p.id)p.textContent=level()}
function balanceData(){const w=app.state?.wallet||{};return{work:Number(w.work_available||0),workPending:Number(w.work_pending||0),ref:Number(w.referral_available||0),refPending:Number(w.referral_pending||0)}}
function renderHome(){const first=(profile().full_name||'Friend').split(' ')[0],chat=chatConfig();renderAppHeader(`${greeting()} , ${first}`.replace(' ,',','),'Ready for your next activity?');$('#header-avatar').textContent=initials(profile().full_name);const b=balanceData(),today=Number(app.state?.today_chats||0),l=levelConfig(),limit=Math.max(1,Number(l.chat_limit||4)),pct=Math.min(100,Math.round(today/limit*100)),reward=format(amountFromBase(l.chat_reward_ngn||250));$('#home-work').textContent=format(b.work);$('#home-work-pending').textContent=`Pending ${format(b.workPending)}`;$('#home-referral').textContent=format(b.ref);$('#home-referral-pending').textContent=`Pending ${format(b.refPending)}`;$('#home-level').textContent=`${level()} level`;$('#home-country').textContent=`${cmeta().name} · ${cmeta().currency}`;$('#home-chat-count').textContent=`${today} / ${limit}`;$('#home-chat-progress').textContent=`${today} of ${limit} guided chats completed`;$('#home-progress-percent').textContent=`${pct}%`;$('#home-chat-bar').style.width=`${pct}%`;$('#home-next-title').textContent=today<limit?(today?'Continue your guided chats':'Complete your first guided chat'):'Explore available linked tasks';$('#home-next-copy').textContent=today<limit?`About ${chat.minimum_seconds} seconds · ${reward} after approval`:'Follow a clear guide and submit your activity';$('#home-next').textContent=today<limit?'Start guided chat':'View tasks';$('#home-next').disabled=featureFlags().guided_chat===false&&today<limit;$('#home-next').onclick=()=>navigate(today<limit?'earn':'tasks');if(!localStorage.getItem('earnchat-tour-complete'))openTour()}
function renderEarn(){const chat=chatConfig();renderAppHeader('Earn','Guided conversations with clear limits and approval.');const today=Number(app.state?.today_chats||0),l=levelConfig(),limit=Math.max(1,Number(l.chat_limit||4)),left=Math.max(0,limit-today),reward=format(amountFromBase(l.chat_reward_ngn||250)),enabled=chat.enabled&&featureFlags().guided_chat!==false;$('#earn-summary').innerHTML=`<header><div><span class="eyebrow">${esc(level().toUpperCase())} CHAT PLAN</span><h3>${left} guided chat${left===1?'':'s'} remaining today</h3><p>${today} of ${limit} approved · ${chat.required_replies} replies · minimum ${chat.minimum_seconds} seconds</p></div><b class="reward">${reward}</b></header><div class="progress"><i style="width:${Math.min(100,today/limit*100)}%"></i></div>`;$('#chat-partners').innerHTML=!enabled?'<article class="list-card"><h3>Guided Chat is unavailable</h3><p>Please choose another activity or return later.</p></article>':left?chatPartners().map(p=>`<article class="list-card partner-card"><header><div class="phone-top"><div class="mini-avatar">${esc(p.short)}</div><div><h3>${esc(p.name)}</h3><p>${esc(p.place)} · ${esc(p.topic)}</p></div></div><b class="reward">${reward}</b></header><span class="tag">Guided conversation partner</span><button class="primary start-chat" data-partner="${esc(p.name)}">Start guided chat</button></article>`).join(''):'<article class="list-card"><h3>Daily chat limit reached</h3><p>Complete linked tasks or return tomorrow for new guided chats.</p></article>';$$('.start-chat').forEach(b=>b.onclick=()=>startChat(b.dataset.partner,b));if(enabled)restoreOpenChatBanner()}
function partnerByName(name){const partners=chatPartners();return partners.find(p=>p.name===name)||partners[0]}
function persistChat(){const key=chatRecoveryKey();if(!app.chat)return localStorage.removeItem(key);localStorage.setItem(key,JSON.stringify({attemptId:app.chat.attemptId,partner:app.chat.partner,startedAt:app.chat.startedAt,stage:app.chat.stage,replies:app.chat.replies,replyTexts:app.chat.replyTexts,promptSet:app.chat.promptSet,savedAt:Date.now(),expiresAt:Date.now()+chatRecoveryMs()}))}
function clearChat(){clearInterval(app.chatTimer);app.chatTimer=null;app.chat=null;localStorage.removeItem(chatRecoveryKey())}
async function restoreOpenChatBanner(){try{const open=await api.openChatAttempt();if(!open)return;let saved=null;try{saved=JSON.parse(localStorage.getItem(chatRecoveryKey())||'null');if(saved?.expiresAt&&Date.now()>Number(saved.expiresAt)){localStorage.removeItem(chatRecoveryKey());saved=null}}catch{localStorage.removeItem(chatRecoveryKey())}const box=document.createElement('article');box.className='list-card resume-card';box.innerHTML=`<h3>Guided chat in progress</h3><p>${saved?.attemptId===open.attempt_id?'Continue your existing replies.':`The timed session is still open. You can restart the ${chatRequiredReplies()} replies or cancel it.`}</p><div class="quick-grid"><button class="primary resume-chat">Resume chat</button><button class="danger cancel-chat">Cancel chat</button></div>`;$('#chat-partners').prepend(box);$('.resume-chat',box).onclick=()=>resumeChat(open,saved);$('.cancel-chat',box).onclick=async()=>{await api.cancelChatAttempt(open.attempt_id);clearChat();box.remove()}}catch{}}
function resumeChat(open,saved){const meta=partnerByName(open.partner||saved?.partner),same=saved?.attemptId===open.attempt_id;app.chat={partner:meta.name,meta,attemptId:open.attempt_id,startedAt:serverTime(open.started_at),stage:same?Number(saved.stage||0):0,replies:same&&Array.isArray(saved.replies)?saved.replies:[],replyTexts:same&&Array.isArray(saved.replyTexts)?saved.replyTexts:[],promptSet:same&&Number.isInteger(Number(saved.promptSet))?Number(saved.promptSet):choosePromptSet(open.attempt_id)};openChatUi(same?'Your timed guided chat has been restored.':`The timer was restored. Complete ${chatRequiredReplies()} new meaningful replies in this browser.`)}
function updateChatTimer(){if(!app.chat)return;const total=chatMinimumSeconds(),required=chatRequiredReplies(),elapsed=Math.max(0,Math.floor((Date.now()-app.chat.startedAt)/1000)),remaining=Math.max(0,total-elapsed),fmt=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;const timer=$('#chat-timer'),complete=$('#chat-complete');if(timer)timer.textContent=`${fmt(Math.min(elapsed,total))} / ${fmt(total)}`;if(app.chat.replies.length===required){$('#chat-ready')?.classList.remove('hidden');if(complete){complete.disabled=remaining>0;complete.textContent=remaining>0?`Ready in ${remaining}s`:chatConfig().completion_wording}}}
async function startChat(partner,button){if(button){button.disabled=true;button.textContent='Opening guided chat…'}try{const attempt=await api.startChat(partner),meta=partnerByName(partner);app.chat={partner,meta,attemptId:attempt.attempt_id,startedAt:serverTime(attempt.started_at),stage:0,replies:[],replyTexts:[],promptSet:choosePromptSet(attempt.attempt_id)};persistChat();openChatUi()}catch(error){alert(error.message||'Guided chat could not start.')}finally{if(button){button.disabled=false;button.textContent='Start guided chat'}}}
function openChatUi(message=''){const set=chatPrompts(),required=chatRequiredReplies(),seconds=chatMinimumSeconds();$('#chat-title').textContent=app.chat.meta.name;$('#chat-subtitle').textContent=`${app.chat.meta.place} · ${app.chat.meta.topic}`;$('#chat-avatar').textContent=app.chat.meta.short;$('#chat-messages').innerHTML='';$('#chat-input').value='';$('#chat-input').disabled=app.chat.replies.length>=required;$('#chat-send').disabled=app.chat.replies.length>=required;$('#chat-ready').classList.add('hidden');const readyCopy=$('#chat-ready small');if(readyCopy)readyCopy.textContent=chatConfig().pending_wording;clearMessage('#chat-message');if(message)showMessage('#chat-message',message,'ok');addChatMessage('them',`Hi, I’m ${app.chat.meta.name.split(' ')[0]} . ${set[0].prompt}`.replace(' .','.'));app.chat.replyTexts.forEach((text,index)=>{addChatMessage('me',text);if(index+1<app.chat.replyTexts.length||app.chat.replyTexts.length<required)addChatMessage('them',set[Math.min(index+1,set.length-1)].prompt)});if(app.chat.replyTexts.length===required)addChatMessage('them',`Thanks for sharing. Your ${required} guided replies are complete. You can finish when the ${seconds}-second timer is ready.`);renderChatStage();clearInterval(app.chatTimer);app.chatTimer=setInterval(updateChatTimer,1000);updateChatTimer();navigate('chat')}
function addChatMessage(side,text){const d=document.createElement('div');d.className=`msg ${side}`;d.textContent=text;$('#chat-messages').appendChild(d);$('#chat-messages').scrollTop=$('#chat-messages').scrollHeight}
function showTyping(next){const box=$('#chat-messages'),d=document.createElement('div');d.className='msg them typing';d.innerHTML='<i></i><i></i><i></i>';box.appendChild(d);box.scrollTop=box.scrollHeight;setTimeout(()=>{d.remove();next()},650)}
function renderChatStage(){if(!app.chat)return;const set=chatPrompts(),required=chatRequiredReplies(),stage=Math.min(app.chat.stage,set.length-1),p=set[stage];$('#chat-progress').textContent=`${app.chat.replies.length} of ${required}`;$('#chat-suggestions').innerHTML=app.chat.replies.length<required?(p?.suggestions||[]).map(x=>`<button type="button">${esc(x)}</button>`).join(''):'';$$('#chat-suggestions button').forEach(b=>b.onclick=()=>{$('#chat-input').value=b.textContent;$('#chat-input').focus()});updateChatTimer()}
async function sendChat(){const required=chatRequiredReplies(),minimumLength=chatMinimumReplyLength();if(!app.chat||app.chat.replies.length>=required)return;const input=$('#chat-input'),text=input.value.trim(),normal=text.toLowerCase().replace(/\s+/g,' ');if(text.length<minimumLength)return showMessage('#chat-message',`Write a more meaningful reply of at least ${minimumLength} characters.`);if(app.chat.replies.includes(normal))return showMessage('#chat-message','Use a different reply instead of repeating the same answer.');clearMessage('#chat-message');input.value='';app.chat.replies.push(normal);app.chat.replyTexts.push(text);addChatMessage('me',text);app.chat.stage++;persistChat();input.disabled=true;$('#chat-send').disabled=true;if(app.chat.replies.length<required){showTyping(()=>{addChatMessage('them',chatPrompts()[Math.min(app.chat.stage,chatPrompts().length-1)].prompt);renderChatStage();input.disabled=false;$('#chat-send').disabled=false;input.focus()})}else showTyping(()=>{addChatMessage('them',`Thanks for sharing. Your ${required} guided replies are complete. You can finish when the ${chatMinimumSeconds()}-second timer is ready.`);renderChatStage()})}
async function completeChat(){const required=chatRequiredReplies(),seconds=chatMinimumSeconds();if(!app.chat||app.chat.replies.length!==required)return;if(Math.floor((Date.now()-app.chat.startedAt)/1000)<seconds)return;document.dispatchEvent(new CustomEvent('earnchat:chat-completion-requested'));$('#chat-complete').disabled=true;$('#chat-complete').textContent='Verifying session…';try{const result=await api.completeChat(app.chat.attemptId,app.chat.replyTexts,{duplicate_replies:false,reply_lengths:app.chat.replies.map(x=>x.length),minimum_seconds:seconds,required_replies:required}),credited=Number(result.amount??0);clearInterval(app.chatTimer);localStorage.removeItem(chatRecoveryKey());showMessage('#chat-message',credited?`Guided chat completed. ${format(credited)} approved.`:'Guided chat completed and recorded.','ok');await refreshState();const remaining=Number(result.remaining??Math.max(0,Number(levelConfig().chat_limit||4)-Number(app.state?.today_chats||0)));$('#chat-ready').innerHTML=`<b>Guided chat completed</b><small>${credited?`${format(credited)} approved · `:''}${remaining} chat${remaining===1?'':'s'} remaining today.</small><p class="next-activity-label">Choose your next activity</p><div class="chat-next-grid"><button class="secondary" data-chat-next="earn">${remaining?'Another chat':'Earn hub'}</button><button class="secondary" data-chat-next="tasks">Tasks</button><button class="secondary" data-chat-next="visits">Sponsored visit</button><button class="secondary" data-chat-next="referrals">Share referral</button><button class="primary" data-chat-next="home">Return Home</button></div>`;$$('[data-chat-next]',$('#chat-ready')).forEach(button=>button.onclick=()=>{const route=button.dataset.chatNext;clearChat();navigate(route)})}catch(e){showMessage('#chat-message',e.message||'Chat could not be approved.');$('#chat-complete').disabled=false;updateChatTimer()}}
async function exitChat(){if(!app.chat)return navigate('earn');if(!confirm('Leave this guided chat? You can resume it until the server attempt expires.'))return;persistChat();navigate('earn')}

async function renderTasks(category=null){const cfg=taskConfig(),enabled=category==='Visit'?cfg.visits_enabled&&featureFlags().sponsored_visits!==false:cfg.enabled&&featureFlags().tasks!==false;renderAppHeader(category==='Visit'?'Visits':'Tasks',category==='Visit'?'Sponsored activities use the same secure task system.':'Every external activity begins with a clear guide.');const host=category==='Visit'?$('#visit-list'):$('#task-list');if(!enabled){host.innerHTML='<article class="list-card"><h3>This activity section is unavailable</h3><p>Please choose another earning option or return later.</p></article>';return}host.innerHTML='<div class="list-card"><b>Loading activities…</b><p>Please wait while available work is checked.</p></div>';try{const rows=(await api.tasks()).filter(r=>category?r.category===category:r.category!=='Visit'),currentRank=Number(levels()[level()]?.rank||0);host.innerHTML=rows.length?rows.map(r=>{const locked=Number(levels()[r.required_level]?.rank||0)>currentRank;return `<article class="list-card ${locked?'lock':''}" data-task-card="${r.id}"><header><div><h3>${esc(r.title)}</h3><p>${esc(r.description||'Follow the provider instructions and return to submit.')}</p></div><b class="reward">${format(amountFromBase(r.base_reward_ngn))}</b></header><span class="tag">${esc(r.category)}</span><span class="tag">${esc(r.required_level)}</span><span class="tag">${Number(r.required_seconds||0)}s</span><div class="guide">1. Read the instructions.<br>2. Open the approved external link.<br>3. Complete the activity.<br>4. Return and submit${r.proof_required?' proof':''}.</div><button class="${locked?'secondary':'primary'} task-start" data-id="${r.id}" ${locked?'disabled':''}>${locked?`Unlock ${esc(r.required_level)} to start`:'View guide and start'}</button></article>`}).join(''):'<article class="list-card"><h3>No activities available right now</h3><p>New work will appear here when the administrator publishes it.</p></article>';$$('.task-start',host).forEach(b=>b.onclick=()=>openTask(rows.find(r=>r.id===b.dataset.id)));await restoreOpenTask(category)}catch(e){host.innerHTML=`<div class="form-message error show">${esc(e.message||'We could not load this section. Check your connection and try again.')}</div>`}}
async function restoreOpenTask(category){try{const c=await api.openTaskClaim();if(!c)return;if(category&&c.category!==category)return;if(!category&&c.category==='Visit')return;app.taskClaim={...c,startedAt:serverTime(c.started_at),task:{id:c.task_id,title:c.title,instructions:c.instructions,required_seconds:c.required_seconds,proof_type:c.proof_type,proof_required:c.proof_required,approval_type:c.approval_type,external_url:c.url}};const host=category==='Visit'?$('#visit-list'):$('#task-list'),card=document.createElement('article');card.className='list-card resume-card restart-required';card.innerHTML=`<h3>Activity not completed</h3><p>${esc(taskConfig().restart_required_message)}</p><small>${esc(c.title)} · opened ${new Date(c.started_at).toLocaleTimeString()}</small><button class="primary restart-task" type="button">Restart task</button>`;host.prepend(card);$('.restart-task',card).onclick=async()=>{const button=$('.restart-task',card);button.disabled=true;button.textContent='Restarting…';try{await api.cancelTask(c.claim_id);app.taskClaim=null;sessionStorage.removeItem('earnchat-task-recovery');await renderTasks(category)}catch(error){button.disabled=false;button.textContent='Restart task';alert(error.message||'The task could not be restarted.')}}}catch{}}
function renderProofField(task){const body=$('#task-modal-body');$('#task-proof-field')?.remove();if((task.proof_type||'none')==='none')return;const wrap=document.createElement('div');wrap.id='task-proof-field';wrap.className='field';if(task.proof_type==='text')wrap.innerHTML='<label>Answer or completion note</label><textarea id="task-proof-value" placeholder="Write the requested answer"></textarea>';else if(task.proof_type==='reference')wrap.innerHTML='<label>Completion reference</label><input id="task-proof-value" placeholder="Enter the reference from the provider">';else wrap.innerHTML='<label>Partner verification token</label><input id="task-proof-value" placeholder="Enter the partner verification token">';body.appendChild(wrap)}
function openTask(task){if(!task)return;openTaskModal(task,false)}
function openTaskModal(task,resumed){clearMessage('#task-modal-message');$('#task-modal-title').textContent=task.title;$('#task-modal-body').innerHTML=`<div class="guide">${esc(task.instructions||'Follow the task instructions carefully. Earn Chat records the start and return time but cannot see everything done on the external site.')}</div><p><b>Reward:</b> ${format(amountFromBase(task.base_reward_ngn||app.taskClaim?.reward||0))}</p><p><b>Required time:</b> ${Number(task.required_seconds||0)} seconds</p><p><b>Approval:</b> ${esc(task.approval_type||'pending')}</p>`;renderProofField(task);$('#task-modal').classList.add('show');if(resumed){$('#task-open').classList.add('hidden');$('#task-submit').classList.remove('hidden');return}$('#task-open').classList.remove('hidden');$('#task-submit').classList.add('hidden');$('#task-open').disabled=false;$('#task-open').onclick=async()=>{document.dispatchEvent(new CustomEvent('earnchat:task-opened',{detail:{taskId:task.id}}));const popup=window.open('about:blank','_blank');try{$('#task-open').disabled=true;const c=await api.startTask(task.id);app.taskClaim={...c,startedAt:serverTime(c.started_at),task};sessionStorage.setItem('earnchat-task-recovery',JSON.stringify({claimId:c.claim_id}));window.dispatchEvent(new CustomEvent('earnchat:task-started',{detail:{claimId:c.claim_id,taskId:task.id}}));if(popup)popup.location.replace(c.url);else location.href=c.url;$('#task-open').classList.add('hidden');$('#task-submit').classList.remove('hidden');showMessage('#task-modal-message','Activity opened. Return after the required time, then submit.','ok')}catch(e){if(popup)popup.close();$('#task-open').disabled=false;showMessage('#task-modal-message',e.message||'Task could not start')}};$('#task-submit').onclick=submitCurrentTask}
async function submitCurrentTask(){if(!app.taskClaim)return;try{const elapsed=Math.floor((Date.now()-app.taskClaim.startedAt)/1000),required=Number(app.taskClaim.required_seconds||app.taskClaim.task?.required_seconds||0);if(elapsed<required)throw new Error(`Wait ${required-elapsed} more seconds before submitting.`);const type=app.taskClaim.proof_type||app.taskClaim.task?.proof_type||'none',value=$('#task-proof-value')?.value.trim()||'';let proof={};if(type==='text'){if(value.length<3)throw new Error('Enter the requested answer.');proof={type,text:value}}else if(type==='reference'){if(value.length<3)throw new Error('Enter the completion reference.');proof={type,reference:value}}else if(type==='partner'){if(value.length<3)throw new Error('Enter the partner verification token.');proof={type,partner_token:value}}const r=await api.submitTask(app.taskClaim.claim_id,proof),credited=Number(r.amount??0),pending=Number(r.pending_amount??0);showMessage('#task-modal-message',r.status==='approved'?`${taskConfig().approved_message} ${format(credited)} credited.`:`${taskConfig().pending_review_message} ${format(pending)} is pending.`,'ok');app.taskClaim=null;sessionStorage.removeItem('earnchat-task-recovery');window.dispatchEvent(new CustomEvent('earnchat:task-submitted',{detail:{claimId:r.claim_id||null,status:r.status||'submitted'}}));await refreshState();setTimeout(()=>{$('#task-modal').classList.remove('show');renderTasks(document.body.dataset.route==='visits'?'Visit':null)},900)}catch(e){showMessage('#task-modal-message',e.message||'Task could not be submitted')}}

async function renderReferrals(){const cfg=referralConfig();renderAppHeader('Referrals','Track genuine activity and qualification progress.');if(!cfg.enabled||featureFlags().referrals===false){$('#ref-list').innerHTML='<article class="list-card"><h3>Referrals are unavailable</h3><p>Please return later.</p></article>';$('#ref-link').value='';return}const b=balanceData(),minimum=amountFromBase(withdrawalConfig().referral_minimum_ngn);$('#ref-balance').textContent=format(b.ref);$('#ref-progress').style.width=`${Math.min(100,b.ref/minimum*100)}%`;$('#ref-remaining').textContent=`${format(Math.max(0,minimum-b.ref))} remaining before referral withdrawal`;const code=profile().referral_code||'',origin=getPublicOrigin(app.config);$('#ref-link').value=code?`${origin}/?ref=${encodeURIComponent(code)}`:'';$('#ref-link').setAttribute('aria-label',cfg.sharing_copy);try{const rows=await api.referrals(profile().id),needed=cfg.required_active_days;$('#ref-list').innerHTML=rows.length?rows.map(r=>{const done=[r.first_active_date,r.second_active_date].filter(Boolean).length;return `<article class="list-card"><header><div><h3>Referral progress</h3><p>Signed up ${new Date(r.signup_at).toLocaleDateString()}</p></div><span class="tag">${esc(r.status)}</span></header><p>${done} of ${needed} qualifying active days</p>${r.review_reason?`<p>${esc(r.review_reason)}</p>`:''}</article>`}).join(''):'<article class="list-card"><h3>No referrals yet</h3><p>Share your referral link and track qualification here.</p></article>'}catch(e){$('#ref-list').innerHTML=`<div class="form-message error show">${esc(e.message||'Referral activity could not load.')}</div>`}}
