async function sendPresence(route=document.body.dataset.route||'landing'){try{await api.presence({p_session_id:presenceSession,p_visitor_id:visitor,p_page_id:route,p_is_visible:!document.hidden,p_country:country(),p_device:innerWidth<700?'mobile':'desktop',p_source:new URLSearchParams(location.search).get('utm_source')||'direct'})}catch{}}
function startPresence(){clearInterval(app.presenceTimer);app.presenceTimer=setInterval(()=>{if(!document.hidden)sendPresence()},60000);document.addEventListener('visibilitychange',()=>{if(document.hidden)api.presenceInactive(presenceSession).catch(()=>{});else{void verifySession();sendPresence()}});window.addEventListener('focus',()=>void verifySession());window.addEventListener('pageshow',()=>void verifySession());window.addEventListener('pagehide',()=>api.presenceInactive(presenceSession).catch(()=>{}))}
async function verifySession(force=false){if(app.explicitLogout)return false;if(!force&&Date.now()-app.lastSessionVerifiedAt<30000)return loggedIn();if(app.sessionVerifyPromise)return app.sessionVerifyPromise;const previousId=app.user?.id||null;const request=(async()=>{try{const result=await api.session(),session=result.session||null,nextId=session?.user?.id||null;app.lastSessionVerifiedAt=Date.now();if(nextId){app.session=session;app.user=session.user;if(!app.state||nextId!==previousId){await api.ensureProfile(null,null);await applyPendingReferral();await refreshState();resolveRoute()}return true}if(previousId||loggedIn()){app.session=null;app.user=null;app.state=null;app.profile=null;resolveRoute()}return false}catch{return loggedIn()}})();app.sessionVerifyPromise=request;try{return await request}finally{if(app.sessionVerifyPromise===request)app.sessionVerifyPromise=null}}
async function boot(){const ref=new URLSearchParams(location.search).get('ref');if(ref)sessionStorage.setItem('earnchat-ref',ref);if(!localStorage.getItem('earnchat-country')){app.suggestedCountry=inferCountry();app.country=app.suggestedCountry}else app.suggestedCountry=app.country;bind();configureRouter({isAuthenticated:loggedIn,routeHandler:onRoute});try{const saved=JSON.parse(localStorage.getItem('earnchat-business-config:v1')||'null');app.config=normalizeBusinessConfig(saved?.data||{})}catch{app.config=normalizeBusinessConfig({})}renderLanding();renderSignupCountry();const configRefresh=api.business().then(data=>{app.config=normalizeBusinessConfig(data);renderSignupCountry();const route=document.body.dataset.route||'landing';if(route!=='admin')return onRoute(route)}).catch(()=>{});try{const result=await api.session();app.session=result.session||null;app.user=app.session?.user||null;if(app.session){await api.ensureProfile(null,null);await applyPendingReferral();await refreshState()}}catch{}finally{$('#startup-loader').classList.add('hidden');resolveRoute();if(!loggedIn())showCountrySuggestion();startPresence();void configRefresh}sb.auth.onAuthStateChange((event,session)=>{clearTimeout(app.authVerifyTimer);if(event==='SIGNED_OUT'){if(app.explicitLogout)return;app.authVerifyTimer=setTimeout(()=>verifySession(true),500);return}if(session?.user){const changed=app.user?.id!==session.user.id;app.session=session;app.user=session.user;if(changed||!app.state)app.authVerifyTimer=setTimeout(async()=>{try{await refreshState();resolveRoute()}catch{}},0)}})}
window.addEventListener('earnchat:config-updated',event=>{if(event.detail?.config)app.config=normalizeBusinessConfig(event.detail.config);const route=document.body.dataset.route||'landing';if(route==='admin')return;Promise.resolve(onRoute(route)).catch(error=>console.error('Configuration refresh failed:',error))});
window.addEventListener('earnchat:config-invalidated',async()=>{try{app.config=normalizeBusinessConfig(await api.refreshBusiness())}catch{return}const route=document.body.dataset.route||'landing';if(route==='admin')return;Promise.resolve(onRoute(route)).catch(error=>console.error('Configuration refresh failed:',error))});
boot();
